-- ============================================================================
-- Minga Parish Management System — migration 01: parish core
--   parish profile, organisational tree (parokia → kigango → jumuiya),
--   families, parishioners (waumini), leadership, parish roles & permissions,
--   audit log.
--
-- Only creates new objects (create ... if not exists / create or replace) and
-- never drops data. Requires auth.users (Supabase) and public.profiles (migration 00).
-- ============================================================================

-- gen_random_uuid() is built into PostgreSQL 13+, no extension needed.

-- ---------------------------------------------------------------------------
-- Audit log (written only by the audit trigger / security-definer functions)
-- ---------------------------------------------------------------------------
create table if not exists public.audit_log (
  id          bigint generated always as identity primary key,
  at          timestamptz not null default now(),
  actor_id    uuid,
  action      text not null,               -- INSERT / UPDATE / DELETE or a business action e.g. 'post_payment'
  table_name  text,
  row_id      text,
  old_data    jsonb,
  new_data    jsonb,
  note        text
);
create index if not exists audit_log_table_row_idx on public.audit_log (table_name, row_id);
create index if not exists audit_log_at_idx on public.audit_log (at desc);

create or replace function public.audit_row()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.audit_log (actor_id, action, table_name, row_id, old_data, new_data)
  values (auth.uid(), tg_op, tg_table_name,
          coalesce((case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end) ->> 'id', ''),
          case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,
          case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end);
  return coalesce(new, old);
end $$;

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;

-- ---------------------------------------------------------------------------
-- Parish profile (single row per parish; multi-parish ready via parish_id)
-- ---------------------------------------------------------------------------
create table if not exists public.parishes (
  id                  uuid primary key default gen_random_uuid(),
  code                text not null unique,                 -- short code used in receipt numbers, e.g. 'MNG'
  official_name       text not null,
  short_name          text,
  patron_saint        text,
  diocese             text,
  region              text,
  district            text,
  postal_address      text,
  physical_address    text,
  phone               text,
  email               text,
  logo_url            text,
  parish_priest       text,
  assistant_priests   text[],
  established_year    int,
  history             text,
  mission             text,
  vision              text,
  fy_start_month      int not null default 1 check (fy_start_month between 1 and 12),
  receipt_title       text default 'STAKABADHI YA MALIPO',
  receipt_prefix      text,
  receipt_footer      text,
  report_header       text,
  report_footer       text,
  payment_accounts    jsonb not null default '[]'::jsonb,   -- [{label, bank, account_no, mobile_number}]
  verified_fields     text[] not null default '{}',         -- which fields an administrator has confirmed
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
drop trigger if exists parishes_touch on public.parishes;
create trigger parishes_touch before update on public.parishes for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Organisational tree: parish → (zone) → kigango → jumuiya, plus parish groups
-- (vyama vya kitume, kwaya, kanda, kamati) that also contribute money.
-- ---------------------------------------------------------------------------
create table if not exists public.org_units (
  id            uuid primary key default gen_random_uuid(),
  parish_id     uuid not null references public.parishes(id),
  parent_id     uuid references public.org_units(id),
  unit_type     text not null check (unit_type in ('parish','zone','kigango','jumuiya','group')),
  name          text not null,
  official_name text,
  ordinal       int,
  zone          text,              -- 'parokiani' (centre) / 'vigangoni' (outstations) as used by the legacy reports
  legacy_names  text[] not null default '{}',   -- spellings found in the workbook, used by the importer
  is_active     boolean not null default true,
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (parish_id, unit_type, name)
);
create index if not exists org_units_parent_idx on public.org_units (parent_id);
drop trigger if exists org_units_touch on public.org_units;
create trigger org_units_touch before update on public.org_units for each row execute function public.touch_updated_at();

-- ancestor/descendant pairs (including self) — small tree, computed on demand
create or replace view public.org_unit_closure with (security_invoker = true) as
with recursive c as (
  select id as ancestor_id, id as descendant_id, 0 as depth from public.org_units
  union all
  select c.ancestor_id, o.id, c.depth + 1
  from c join public.org_units o on o.parent_id = c.descendant_id
)
select * from c;

-- nearest ancestor (or self) of a given type
create or replace function public.org_ancestor_of_type(p_unit uuid, p_type text)
returns uuid language sql stable set search_path = public as $$
  with recursive up as (
    select id, parent_id, unit_type, 0 as d from public.org_units where id = p_unit
    union all
    select o.id, o.parent_id, o.unit_type, up.d + 1 from public.org_units o join up on o.id = up.parent_id
  )
  select id from up where unit_type = p_type order by d limit 1
$$;

create or replace function public.org_is_within(p_unit uuid, p_scope uuid)
returns boolean language sql stable set search_path = public as $$
  with recursive up as (
    select id, parent_id from public.org_units where id = p_unit
    union all
    select o.id, o.parent_id from public.org_units o join up on o.id = up.parent_id
  )
  select p_scope is null or exists (select 1 from up where id = p_scope)
$$;

-- p_scope and every unit below it (computed once per query; use with "= any")
create or replace function public.units_within(p_scope uuid)
returns uuid[] language sql stable set search_path = public as $$
  with recursive down as (
    select id from public.org_units where id = p_scope
    union
    select o.id from public.org_units o join down d on o.parent_id = d.id
  )
  select coalesce(array_agg(id), '{}'::uuid[]) from down
$$;

-- ---------------------------------------------------------------------------
-- Families and parishioners (parish register — independent of login accounts)
-- ---------------------------------------------------------------------------
create table if not exists public.families (
  id              uuid primary key default gen_random_uuid(),
  parish_id       uuid not null references public.parishes(id),
  family_code     text,                                  -- e.g. legacy "FAMILIA NAMBA" within the jumuiya
  family_name     text not null,
  jumuiya_id      uuid references public.org_units(id),
  head_parishioner_id uuid,                              -- FK added after parishioners exists
  phone           text,
  address         text,
  status          text not null default 'active' check (status in ('active','inactive','moved','merged')),
  legacy_ref      jsonb,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (parish_id, jumuiya_id, family_code)
);
create index if not exists families_jumuiya_idx on public.families (jumuiya_id);
drop trigger if exists families_touch on public.families;
create trigger families_touch before update on public.families for each row execute function public.touch_updated_at();

create table if not exists public.parishioners (
  id               uuid primary key default gen_random_uuid(),
  parish_id        uuid not null references public.parishes(id),
  member_no        text,                                 -- parish register number
  full_name        text not null,
  gender           text check (gender in ('male','female')),
  birth_year       int check (birth_year between 1900 and 2100),
  phone            text,
  family_id        uuid references public.families(id),
  relationship     text,                                 -- BABA, MAMA, MTOTO, ... (legacy UHUSIANO)
  jumuiya_id       uuid references public.org_units(id), -- current jumuiya (denormalised from family for people without a family)
  is_zaka_payer    boolean not null default false,       -- legacy "UTAMBUZI WA MLIPA ZAKA"
  membership_status text not null default 'active' check (membership_status in ('active','inactive','moved','deceased')),
  registered_on    date,
  profile_id       uuid unique references auth.users(id) on delete set null,  -- linked login account (verified by an admin)
  notes            text,
  legacy_ref       jsonb,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (parish_id, member_no)
);
create index if not exists parishioners_family_idx on public.parishioners (family_id);
create index if not exists parishioners_jumuiya_idx on public.parishioners (jumuiya_id);
create index if not exists parishioners_name_idx on public.parishioners (lower(full_name));
drop trigger if exists parishioners_touch on public.parishioners;
create trigger parishioners_touch before update on public.parishioners for each row execute function public.touch_updated_at();

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'families_head_fk') then
    alter table public.families add constraint families_head_fk
      foreign key (head_parishioner_id) references public.parishioners(id) on delete set null;
  end if;
end $$;

-- membership history (transfers between families / jumuiya keep the old attribution traceable)
create table if not exists public.membership_history (
  id              bigint generated always as identity primary key,
  parishioner_id  uuid references public.parishioners(id) on delete cascade,
  family_id       uuid references public.families(id) on delete cascade,
  from_jumuiya_id uuid references public.org_units(id),
  to_jumuiya_id   uuid references public.org_units(id),
  from_family_id  uuid references public.families(id),
  to_family_id    uuid references public.families(id),
  changed_on      date not null default current_date,
  reason          text,
  changed_by      uuid,
  created_at      timestamptz not null default now()
);

create or replace function public.track_membership_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_table_name = 'parishioners' then
    if new.jumuiya_id is distinct from old.jumuiya_id or new.family_id is distinct from old.family_id then
      insert into public.membership_history (parishioner_id, from_jumuiya_id, to_jumuiya_id, from_family_id, to_family_id, changed_by)
      values (new.id, old.jumuiya_id, new.jumuiya_id, old.family_id, new.family_id, auth.uid());
    end if;
  elsif new.jumuiya_id is distinct from old.jumuiya_id then
    insert into public.membership_history (family_id, from_jumuiya_id, to_jumuiya_id, changed_by)
    values (new.id, old.jumuiya_id, new.jumuiya_id, auth.uid());
    -- members of the family follow it
    update public.parishioners set jumuiya_id = new.jumuiya_id
     where family_id = new.id and jumuiya_id is not distinct from old.jumuiya_id;
  end if;
  return new;
end $$;
drop trigger if exists parishioners_membership on public.parishioners;
create trigger parishioners_membership after update on public.parishioners for each row execute function public.track_membership_change();
drop trigger if exists families_membership on public.families;
create trigger families_membership after update on public.families for each row execute function public.track_membership_change();

-- ---------------------------------------------------------------------------
-- Church leadership (separate from application permissions)
-- ---------------------------------------------------------------------------
create table if not exists public.leadership_positions (
  id          uuid primary key default gen_random_uuid(),
  code        text not null unique,
  title_sw    text not null,
  title_en    text,
  level       text not null check (level in ('parish','kigango','jumuiya','group')),
  sort_order  int not null default 100
);

create table if not exists public.leadership_assignments (
  id              uuid primary key default gen_random_uuid(),
  position_id     uuid not null references public.leadership_positions(id),
  org_unit_id     uuid not null references public.org_units(id),
  parishioner_id  uuid references public.parishioners(id),
  holder_name     text not null,               -- kept even when the person is not in the register
  phone           text,
  starts_on       date,
  ends_on         date,
  status          text not null default 'active' check (status in ('active','ended')),
  notes           text,
  created_at      timestamptz not null default now(),
  check (ends_on is null or starts_on is null or ends_on >= starts_on)
);
create index if not exists leadership_org_idx on public.leadership_assignments (org_unit_id);

-- ---------------------------------------------------------------------------
-- Parish application roles & permissions (granular, scoped to an org unit)
--   profiles.role = 'super_admin' (migration 00) is the system administrator;
--   everyone else gets access only through parish_user_roles.
-- ---------------------------------------------------------------------------
create table if not exists public.parish_roles (
  code        text primary key,
  name_sw     text not null,
  name_en     text not null,
  scoped      boolean not null default false,     -- true = must be tied to a kigango/jumuiya
  sort_order  int not null default 100
);

create table if not exists public.role_permissions (
  role_code   text not null references public.parish_roles(code) on delete cascade,
  permission  text not null,
  primary key (role_code, permission)
);

create table if not exists public.parish_user_roles (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete cascade,
  parish_id   uuid not null references public.parishes(id),
  role_code   text not null references public.parish_roles(code),
  org_unit_id uuid references public.org_units(id),        -- null = whole parish
  granted_by  uuid,
  granted_at  timestamptz not null default now(),
  unique (user_id, role_code, org_unit_id)
);
create index if not exists parish_user_roles_user_idx on public.parish_user_roles (user_id);

create or replace function public.is_platform_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'super_admin' and coalesce(status,'active') = 'active')
$$;

-- has_perm(permission, org_unit): true when the user holds a role granting the
-- permission whose scope is the whole parish or an ancestor of p_org.
-- p_org = null asks for parish-wide permission.
create or replace function public.has_perm(p_perm text, p_org uuid default null)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_platform_admin() or exists (
    select 1
    from public.parish_user_roles ur
    join public.role_permissions rp on rp.role_code = ur.role_code
    where ur.user_id = auth.uid()
      and rp.permission = p_perm
      and (case when ur.org_unit_id is null then true
                when p_org is null then false
                else public.org_is_within(p_org, ur.org_unit_id) end)
  )
$$;

-- any scope at all (used to decide whether a menu item should be shown)
create or replace function public.has_perm_anywhere(p_perm text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_platform_admin() or exists (
    select 1 from public.parish_user_roles ur join public.role_permissions rp on rp.role_code = ur.role_code
    where ur.user_id = auth.uid() and rp.permission = p_perm)
$$;

create or replace function public.my_parishioner_id()
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.parishioners where profile_id = auth.uid() limit 1
$$;

create or replace function public.my_family_id()
returns uuid language sql stable security definer set search_path = public as $$
  select family_id from public.parishioners where profile_id = auth.uid() limit 1
$$;

-- what the current user may do — consumed by the frontend to build its menu
create or replace function public.my_parish_access()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'platform_admin', public.is_platform_admin(),
    'parishioner_id', public.my_parishioner_id(),
    'roles', coalesce((select jsonb_agg(jsonb_build_object('role', ur.role_code, 'org_unit_id', ur.org_unit_id,
                                 'org_unit', o.name, 'unit_type', o.unit_type))
                       from public.parish_user_roles ur left join public.org_units o on o.id = ur.org_unit_id
                       where ur.user_id = auth.uid()), '[]'::jsonb),
    'permissions', coalesce((select jsonb_agg(distinct rp.permission)
                             from public.parish_user_roles ur join public.role_permissions rp on rp.role_code = ur.role_code
                             where ur.user_id = auth.uid()), '[]'::jsonb)
  )
$$;

-- audit triggers on register tables
do $$ declare t text; begin
  foreach t in array array['parishes','org_units','families','parishioners','leadership_assignments','parish_user_roles','role_permissions'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row()', t || '_audit', t);
  end loop;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261015_02_finance_core.sql >>>>>>>>>>>>>>>>>>>>
-- ============================================================================
-- Minga Parish Management System — migration 02: financial data model
--   One authoritative ledger (finance_transactions). Every report, balance,
--   dashboard figure and receipt is derived from it — nothing is copied.
--
--   Money is NUMERIC(14,2). Posted rows are immutable; corrections are made
--   with reversal transactions (sign = -1) or adjustments.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Financial years and monthly accounting periods
-- ---------------------------------------------------------------------------
create table if not exists public.financial_years (
  id         uuid primary key default gen_random_uuid(),
  parish_id  uuid not null references public.parishes(id),
  label      text not null,                 -- '2026'
  starts_on  date not null,
  ends_on    date not null,
  status     text not null default 'open' check (status in ('open','closed')),
  closed_at  timestamptz,
  closed_by  uuid,
  unique (parish_id, label),
  check (ends_on > starts_on)
);

create table if not exists public.accounting_periods (
  id                 uuid primary key default gen_random_uuid(),
  financial_year_id  uuid not null references public.financial_years(id) on delete cascade,
  period_start       date not null,
  period_end         date not null,
  is_locked          boolean not null default false,
  locked_at          timestamptz,
  locked_by          uuid,
  unique (financial_year_id, period_start)
);

-- ---------------------------------------------------------------------------
-- Funds and chart of accounts (double entry)
-- ---------------------------------------------------------------------------
create table if not exists public.funds (
  id          uuid primary key default gen_random_uuid(),
  parish_id   uuid not null references public.parishes(id),
  code        text not null,
  name        text not null,
  is_restricted boolean not null default false,   -- e.g. Ujenzi money may only be spent on construction
  description text,
  unique (parish_id, code)
);

create table if not exists public.ledger_accounts (
  id            uuid primary key default gen_random_uuid(),
  parish_id     uuid not null references public.parishes(id),
  code          text not null,
  name          text not null,
  account_type  text not null check (account_type in ('asset','liability','equity','income','expense')),
  money_kind    text check (money_kind in ('cash','bank','mobile_money')),  -- set for accounts that hold money
  bank_name     text,
  account_number text,
  fund_id       uuid references public.funds(id),
  is_active     boolean not null default true,
  unique (parish_id, code)
);

-- ---------------------------------------------------------------------------
-- Contribution categories (aina za michango) and campaigns (per year)
-- ---------------------------------------------------------------------------
create table if not exists public.contribution_categories (
  id                 uuid primary key default gen_random_uuid(),
  parish_id          uuid not null references public.parishes(id),
  code               text not null,
  name_sw            text not null,
  name_en            text,
  kind               text not null check (kind in ('zaka','mavuno','ujenzi','sadaka','special','shukrani','income_other','expense')),
  is_pledgeable      boolean not null default false,
  uses_period_month  boolean not null default false,   -- Zaka: the month the payment is for
  fund_id            uuid references public.funds(id),
  income_account_id  uuid references public.ledger_accounts(id),
  expense_account_id uuid references public.ledger_accounts(id),
  legacy_labels      text[] not null default '{}',
  is_active          boolean not null default true,
  sort_order         int not null default 100,
  unique (parish_id, code)
);

create table if not exists public.campaigns (
  id                  uuid primary key default gen_random_uuid(),
  parish_id           uuid not null references public.parishes(id),
  category_id         uuid not null references public.contribution_categories(id),
  financial_year_id   uuid references public.financial_years(id),
  campaign_year       int not null,
  name                text not null,
  description         text,
  starts_on           date,
  ends_on             date,
  target_amount       numeric(14,2) check (target_amount is null or target_amount >= 0),
  overpayment_policy  text not null default 'record_as_excess'
                      check (overpayment_policy in ('record_as_excess','credit_next_campaign')),
  status              text not null default 'active' check (status in ('draft','active','closed')),
  recurs_annually     boolean not null default false,
  previous_campaign_id uuid references public.campaigns(id),
  event_id            uuid,                 -- reserved for a future events module (no foreign key)
  created_at          timestamptz not null default now(),
  unique (parish_id, category_id, campaign_year, name)
);

-- assessments per community ("WALICHOPANGIWA"): fixed, or units × rate (families × 60,000 …)
create table if not exists public.campaign_targets (
  id            uuid primary key default gen_random_uuid(),
  campaign_id   uuid not null references public.campaigns(id) on delete cascade,
  org_unit_id   uuid not null references public.org_units(id),
  basis         text not null default 'fixed' check (basis in ('fixed','per_family','per_member')),
  fixed_amount  numeric(14,2) check (fixed_amount is null or fixed_amount >= 0),
  unit_count    int check (unit_count is null or unit_count >= 0),
  unit_rate     numeric(14,2) check (unit_rate is null or unit_rate >= 0),
  target_amount numeric(14,2) generated always as (
                  case when basis = 'fixed' then fixed_amount else coalesce(unit_count,0) * coalesce(unit_rate,0) end) stored,
  notes         text,
  unique (campaign_id, org_unit_id),
  check ((basis = 'fixed' and fixed_amount is not null) or (basis <> 'fixed' and unit_count is not null and unit_rate is not null))
);

-- ---------------------------------------------------------------------------
-- Pledges (ahadi) — by a parishioner, a family or a whole community
-- ---------------------------------------------------------------------------
create table if not exists public.pledges (
  id                uuid primary key default gen_random_uuid(),
  parish_id         uuid not null references public.parishes(id),
  campaign_id       uuid not null references public.campaigns(id),
  parishioner_id    uuid references public.parishioners(id),
  family_id         uuid references public.families(id),
  org_unit_id       uuid references public.org_units(id),
  amount            numeric(14,2) not null check (amount > 0),
  pledged_on        date not null default current_date,
  due_on            date,
  status            text not null default 'active' check (status in ('active','cancelled','carried_forward')),
  status_reason     text,
  carried_from_id   uuid references public.pledges(id),
  -- attribution snapshot (kept when the family later moves)
  jumuiya_id        uuid references public.org_units(id),
  kigango_id        uuid references public.org_units(id),
  legacy_ref        jsonb,
  created_by        uuid,
  created_at        timestamptz not null default now(),
  check (num_nonnulls(parishioner_id, family_id, org_unit_id) = 1)
);
create unique index if not exists pledges_one_active_per_payer
  on public.pledges (campaign_id, coalesce(parishioner_id, family_id, org_unit_id)) where status = 'active';
create index if not exists pledges_campaign_idx on public.pledges (campaign_id);

-- contribution rules per campaign and the kind of obligation (see migration 13)
alter table public.campaigns add column if not exists giver_level text
  check (giver_level is null or giver_level in ('parishioner','family','jumuiya','kigango'));
alter table public.campaigns add column if not exists amount_mode text not null default 'pledge'
  check (amount_mode in ('assigned','pledge','free'));
alter table public.campaigns add column if not exists frequency text not null default 'yearly'
  check (frequency in ('yearly','monthly'));
alter table public.campaigns add column if not exists default_amount numeric(14,2)
  check (default_amount is null or default_amount >= 0);
alter table public.campaigns add column if not exists relation_rates jsonb not null default '{}'::jsonb;

alter table public.pledges add column if not exists source text not null default 'pledge'
  check (source in ('pledge','assigned'));

-- ---------------------------------------------------------------------------
-- THE LEDGER
-- ---------------------------------------------------------------------------
create table if not exists public.finance_transactions (
  id                 uuid primary key default gen_random_uuid(),
  txn_no             bigint generated always as identity unique,
  parish_id          uuid not null references public.parishes(id),
  idempotency_key    uuid not null unique,                 -- one key per form submission: retries/double clicks reuse it
  kind               text not null check (kind in ('income','expense','transfer','opening_balance','adjustment')),
  sign               smallint not null default 1 check (sign in (1,-1)),   -- -1 = reversal of another row
  amount             numeric(14,2) not null check (amount > 0),
  net_amount         numeric(14,2) generated always as (amount * sign) stored,
  status             text not null default 'posted' check (status in ('pending','posted','rejected')),
  txn_date           date not null,
  financial_year_id  uuid not null references public.financial_years(id),
  period_month       date,                                 -- Zaka month the payment is for (1st of month)
  category_id        uuid not null references public.contribution_categories(id),
  campaign_id        uuid references public.campaigns(id),
  pledge_id          uuid references public.pledges(id),    -- primary obligation the payment was taken against
  fund_id            uuid references public.funds(id),
  money_account_id   uuid not null references public.ledger_accounts(id),   -- cash / bank / mobile money
  to_account_id      uuid references public.ledger_accounts(id),            -- transfers only
  parishioner_id     uuid references public.parishioners(id),
  family_id          uuid references public.families(id),
  org_unit_id        uuid references public.org_units(id),   -- community / group the money is credited to
  jumuiya_id         uuid references public.org_units(id),   -- attribution snapshot at posting time
  kigango_id         uuid references public.org_units(id),
  payer_name         text,
  payment_method     text not null default 'cash'
                     check (payment_method in ('cash','cheque','bank_transfer','mobile_money','envelope','other')),
  reference_no       text,                                 -- bank / mobile money / cheque reference
  description        text,
  reverses_id        uuid references public.finance_transactions(id),
  reversed_by_id     uuid references public.finance_transactions(id),
  reversal_reason    text,
  event_id           uuid,
  envelope_id        uuid,
  recorded_by        uuid,
  approved_by        uuid,
  posted_at          timestamptz,
  legacy_receipt_no  text,
  legacy_ref         jsonb,                                -- {sheet,row,...} for imported history
  import_batch_id    uuid,
  created_at         timestamptz not null default now(),
  check (sign = 1 or reverses_id is not null),
  check (kind <> 'transfer' or to_account_id is not null)
);
create index if not exists ft_date_idx      on public.finance_transactions (txn_date);
create index if not exists ft_fy_idx        on public.finance_transactions (financial_year_id);
create index if not exists ft_category_idx  on public.finance_transactions (category_id);
create index if not exists ft_campaign_idx  on public.finance_transactions (campaign_id);
create index if not exists ft_pledge_idx    on public.finance_transactions (pledge_id);
create index if not exists ft_family_idx    on public.finance_transactions (family_id);
create index if not exists ft_parishioner_idx on public.finance_transactions (parishioner_id);
create index if not exists ft_jumuiya_idx   on public.finance_transactions (jumuiya_id);
create index if not exists ft_kigango_idx   on public.finance_transactions (kigango_id);
-- the same external payment reference can be posted only once
create unique index if not exists ft_unique_external_ref
  on public.finance_transactions (payment_method, lower(btrim(reference_no)))
  where reference_no is not null and btrim(reference_no) <> '' and sign = 1 and status <> 'rejected'
        and payment_method in ('cheque','bank_transfer','mobile_money');
-- one reversal per original
create unique index if not exists ft_one_reversal on public.finance_transactions (reverses_id) where reverses_id is not null;

-- payment allocations: how much of a payment went to which pledge (split payments)
create table if not exists public.payment_allocations (
  id              uuid primary key default gen_random_uuid(),
  transaction_id  uuid not null references public.finance_transactions(id),
  pledge_id       uuid not null references public.pledges(id),
  amount          numeric(14,2) not null check (amount > 0),
  created_at      timestamptz not null default now(),
  unique (transaction_id, pledge_id)
);
create index if not exists payment_allocations_pledge_idx on public.payment_allocations (pledge_id);

-- ---------------------------------------------------------------------------
-- Double-entry journal (generated from the ledger by the posting functions)
-- ---------------------------------------------------------------------------
create table if not exists public.journal_entries (
  id              uuid primary key default gen_random_uuid(),
  parish_id       uuid not null references public.parishes(id),
  transaction_id  uuid unique references public.finance_transactions(id),
  entry_date      date not null,
  memo            text,
  created_at      timestamptz not null default now()
);

create table if not exists public.journal_lines (
  id          bigint generated always as identity primary key,
  entry_id    uuid not null references public.journal_entries(id),
  account_id  uuid not null references public.ledger_accounts(id),
  fund_id     uuid references public.funds(id),
  debit       numeric(14,2) not null default 0 check (debit >= 0),
  credit      numeric(14,2) not null default 0 check (credit >= 0),
  check ((debit = 0) <> (credit = 0))
);
create index if not exists journal_lines_entry_idx on public.journal_lines (entry_id);
create index if not exists journal_lines_account_idx on public.journal_lines (account_id);

-- every journal entry must balance (checked at commit)
create or replace function public.check_journal_balanced()
returns trigger language plpgsql as $$
declare d numeric; c numeric; e uuid := coalesce(new.entry_id, old.entry_id);
begin
  select coalesce(sum(debit),0), coalesce(sum(credit),0) into d, c from public.journal_lines where entry_id = e;
  if d <> c then
    raise exception 'Journal entry % haijalingana: debit % <> credit %', e, d, c using errcode = '23514';
  end if;
  return null;
end $$;
drop trigger if exists journal_lines_balanced on public.journal_lines;
create constraint trigger journal_lines_balanced after insert or update or delete on public.journal_lines
  deferrable initially deferred for each row execute function public.check_journal_balanced();

-- ---------------------------------------------------------------------------
-- Receipts (risiti) — transaction-safe numbering per series and year
-- ---------------------------------------------------------------------------
create table if not exists public.receipt_counters (
  parish_id  uuid not null references public.parishes(id),
  series     text not null,           -- e.g. '2026'
  last_no    bigint not null default 0,
  primary key (parish_id, series)
);

create table if not exists public.receipts (
  id              uuid primary key default gen_random_uuid(),
  parish_id       uuid not null references public.parishes(id),
  receipt_no      text not null unique,
  series          text not null,
  seq             bigint not null,
  transaction_id  uuid not null unique references public.finance_transactions(id),
  issued_at       timestamptz not null default now(),
  issued_by       uuid,
  receiving_officer text,
  payer_name      text,
  amount          numeric(14,2) not null,
  amount_words_sw text,
  amount_words_en text,
  verification_code text not null default upper(substr(md5(gen_random_uuid()::text), 1, 10)),
  status          text not null default 'valid' check (status in ('valid','void')),
  void_reason     text,
  print_count     int not null default 0,
  last_printed_at timestamptz,
  unique (parish_id, series, seq)
);

-- ---------------------------------------------------------------------------
-- Approvals (expenses and other actions needing a second person)
-- ---------------------------------------------------------------------------
create table if not exists public.approval_requests (
  id              uuid primary key default gen_random_uuid(),
  parish_id       uuid not null references public.parishes(id),
  request_type    text not null check (request_type in ('expense','reversal','adjustment','period_unlock','legacy_review')),
  transaction_id  uuid references public.finance_transactions(id),
  payload         jsonb,
  status          text not null default 'pending' check (status in ('pending','approved','rejected')),
  requested_by    uuid,
  requested_at    timestamptz not null default now(),
  decided_by      uuid,
  decided_at      timestamptz,
  decision_note   text
);

-- ---------------------------------------------------------------------------
-- Envelopes (bahasha): distribution is NOT income — only the linked posted
-- transaction counts.
-- ---------------------------------------------------------------------------
create table if not exists public.envelope_batches (
  id            uuid primary key default gen_random_uuid(),
  parish_id     uuid not null references public.parishes(id),
  campaign_id   uuid references public.campaigns(id),
  category_id   uuid references public.contribution_categories(id),
  name          text not null,
  issued_on     date,
  due_on        date,
  expected_amount_per_envelope numeric(14,2),
  notes         text,
  created_at    timestamptz not null default now()
);

create table if not exists public.envelopes (
  id              uuid primary key default gen_random_uuid(),
  batch_id        uuid not null references public.envelope_batches(id) on delete cascade,
  envelope_no     text not null,
  parishioner_id  uuid references public.parishioners(id),
  family_id       uuid references public.families(id),
  org_unit_id     uuid references public.org_units(id),
  expected_amount numeric(14,2),
  distributed_on  date,
  returned_on     date,
  status          text not null default 'unissued' check (status in ('unissued','distributed','returned','lost','cancelled')),
  transaction_id  uuid references public.finance_transactions(id),
  notes           text,
  unique (batch_id, envelope_no)
);
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'ft_envelope_fk') then
    alter table public.finance_transactions add constraint ft_envelope_fk foreign key (envelope_id) references public.envelopes(id);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Imports from the legacy workbook
-- ---------------------------------------------------------------------------
create table if not exists public.import_batches (
  id            uuid primary key default gen_random_uuid(),
  parish_id     uuid not null references public.parishes(id),
  source_name   text not null,
  source_sha256 text,
  status        text not null default 'preview' check (status in ('preview','approved','imported','rejected')),
  summary       jsonb,
  created_by    uuid,
  created_at    timestamptz not null default now(),
  approved_by   uuid,
  approved_at   timestamptz
);

create table if not exists public.import_issues (
  id          bigint generated always as identity primary key,
  batch_id    uuid not null references public.import_batches(id) on delete cascade,
  severity    text not null check (severity in ('info','warning','error')),
  sheet       text,
  cell_ref    text,
  issue       text not null,
  detail      jsonb,
  resolution  text
);

-- formula-parity results (Excel vs database) kept for the reconciliation dashboard
create table if not exists public.reconciliation_results (
  id            bigint generated always as identity primary key,
  batch_id      uuid references public.import_batches(id) on delete cascade,
  sheet         text not null,
  cell_ref      text not null,
  description   text,
  excel_formula text,
  excel_value   numeric(16,2),
  system_value  numeric(16,2),
  difference    numeric(16,2) generated always as (coalesce(system_value,0) - coalesce(excel_value,0)) stored,
  status        text not null check (status in ('match','difference','excel_error','not_comparable')),
  explanation   text,
  resolution    text,
  checked_at    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Immutability of posted ledger rows
-- ---------------------------------------------------------------------------
create or replace function public.protect_posted_transactions()
returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'posted' then
      raise exception 'Muamala uliothibitishwa hauwezi kufutwa — tumia reversal' using errcode = '42501';
    end if;
    return old;
  end if;
  if old.status = 'posted' then
    -- only the reversal link may be set on a posted row
    -- (net_amount is generated: it is still NULL in NEW inside a BEFORE trigger)
    if (to_jsonb(new) - 'reversed_by_id' - 'reversal_reason' - 'net_amount')
       is distinct from (to_jsonb(old) - 'reversed_by_id' - 'reversal_reason' - 'net_amount') then
      raise exception 'Muamala uliothibitishwa hauwezi kubadilishwa — tumia reversal au adjustment' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists finance_transactions_protect on public.finance_transactions;
create trigger finance_transactions_protect before update or delete on public.finance_transactions
  for each row execute function public.protect_posted_transactions();

create or replace function public.protect_immutable()
returns trigger language plpgsql as $$
begin
  raise exception '% ni kumbukumbu za kudumu (append-only)', tg_table_name using errcode = '42501';
end $$;
do $$ declare t text; begin
  foreach t in array array['journal_lines','journal_entries','payment_allocations','audit_log'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_immutable', t);
    execute format('create trigger %I before update or delete on public.%I for each row execute function public.protect_immutable()', t || '_immutable', t);
  end loop;
end $$;

-- audit triggers on finance configuration tables (ledger rows are audited by the posting functions)
do $$ declare t text; begin
  foreach t in array array['financial_years','accounting_periods','funds','ledger_accounts','contribution_categories',
                           'campaigns','campaign_targets','pledges','receipts','approval_requests','envelope_batches','envelopes'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row()', t || '_audit', t);
  end loop;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261015_03_finance_functions.sql >>>>>>>>>>>>>>>>>>>>
-- ============================================================================
-- Minga Parish Management System — migration 03: posting engine
--   All writes to the ledger go through these SECURITY DEFINER functions.
--   Each function checks permissions itself (has_perm), runs in one database
--   transaction, and is idempotent where the UI can retry.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.fin_year_for(p_parish uuid, p_date date)
returns uuid language sql stable set search_path = public as $$
  select id from public.financial_years
  where parish_id = p_parish and p_date between starts_on and ends_on
  order by starts_on desc limit 1
$$;

create or replace function public.assert_period_open(p_parish uuid, p_date date)
returns uuid language plpgsql stable set search_path = public as $$
declare fy public.financial_years;
begin
  select * into fy from public.financial_years
   where parish_id = p_parish and p_date between starts_on and ends_on order by starts_on desc limit 1;
  if fy.id is null then
    raise exception 'Hakuna mwaka wa fedha unaojumuisha tarehe % (No financial year covers %)', p_date, p_date using errcode = 'P0001';
  end if;
  if fy.status = 'closed' then
    raise exception 'Mwaka wa fedha % umefungwa (financial year closed)', fy.label using errcode = 'P0001';
  end if;
  if exists (select 1 from public.accounting_periods
             where financial_year_id = fy.id and p_date between period_start and period_end and is_locked) then
    raise exception 'Kipindi cha % kimefungwa (period locked)', to_char(p_date, 'YYYY-MM') using errcode = 'P0001';
  end if;
  return fy.id;
end $$;

create or replace function public.default_parish_id()
returns uuid language sql stable set search_path = public as $$
  select id from public.parishes order by created_at limit 1
$$;

create or replace function public.money_account_for(p_parish uuid, p_method text, p_account uuid)
returns uuid language plpgsql stable set search_path = public as $$
declare v uuid; k text;
begin
  if p_account is not null then
    select id into v from public.ledger_accounts
     where id = p_account and parish_id = p_parish and money_kind is not null and is_active;
    if v is null then raise exception 'Akaunti ya fedha si sahihi (invalid money account)' using errcode = 'P0001'; end if;
    return v;
  end if;
  k := case p_method when 'cash' then 'cash' when 'envelope' then 'cash' when 'mobile_money' then 'mobile_money' else 'bank' end;
  select id into v from public.ledger_accounts
   where parish_id = p_parish and money_kind = k and is_active order by code limit 1;
  if v is null then raise exception 'Hakuna akaunti ya fedha ya aina % (no % account configured)', k, k using errcode = 'P0001'; end if;
  return v;
end $$;

-- resolve jumuiya / kigango snapshot for a payer
create or replace function public.resolve_attribution(p_parishioner uuid, p_family uuid, p_org uuid,
  out family_id uuid, out jumuiya_id uuid, out kigango_id uuid, out org_unit_id uuid)
language plpgsql stable set search_path = public as $$
declare t text;
begin
  family_id := p_family;
  if p_parishioner is not null then
    select coalesce(p.family_id, p_family), coalesce(p.jumuiya_id, f.jumuiya_id)
      into family_id, jumuiya_id
      from public.parishioners p left join public.families f on f.id = p.family_id where p.id = p_parishioner;
    if not found then raise exception 'Muumini hayupo (parishioner not found)' using errcode = 'P0001'; end if;
  end if;
  if jumuiya_id is null and family_id is not null then
    select f.jumuiya_id into jumuiya_id from public.families f where f.id = family_id;
  end if;
  org_unit_id := coalesce(p_org, jumuiya_id);
  if jumuiya_id is null and org_unit_id is not null then
    jumuiya_id := public.org_ancestor_of_type(org_unit_id, 'jumuiya');
  end if;
  if org_unit_id is not null then
    kigango_id := public.org_ancestor_of_type(org_unit_id, 'kigango');
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Amount in words (Kiswahili and English) for receipts
-- ---------------------------------------------------------------------------
create or replace function public.amount_words_sw(p numeric)
returns text language plpgsql immutable as $$
declare n bigint := trunc(abs(p)); cents int := round((abs(p) - trunc(abs(p))) * 100);
begin
  if n = 0 and cents = 0 then return 'Shilingi sifuri'; end if;
  return 'Shilingi ' || public._sw_words(n)
         || case when cents > 0 then ' na senti ' || public._sw_words(cents) else '' end;
end $$;

create or replace function public._sw_words(n bigint)
returns text language plpgsql immutable as $$
declare
  units text[] := array['moja','mbili','tatu','nne','tano','sita','saba','nane','tisa'];
  tens  text[] := array['kumi','ishirini','thelathini','arobaini','hamsini','sitini','sabini','themanini','tisini'];
  r bigint;
begin
  if n = 0 then return ''; end if;
  if n < 10 then return units[n]; end if;
  if n < 100 then
    return tens[n / 10] || case when n % 10 > 0 then ' na ' || units[n % 10] else '' end;
  end if;
  if n < 1000 then
    r := n % 100;
    return 'mia ' || units[n / 100] || case when r > 0 then ' na ' || public._sw_words(r) else '' end;
  end if;
  if n < 100000 then
    r := n % 1000;
    return 'elfu ' || public._sw_words(n / 1000) || case when r > 0 then ' na ' || public._sw_words(r) else '' end;
  end if;
  if n < 1000000 then
    r := n % 100000;
    return 'laki ' || units[n / 100000] || case when r > 0 then ' na ' || public._sw_words(r) else '' end;
  end if;
  if n < 1000000000 then
    r := n % 1000000;
    return 'milioni ' || public._sw_words(n / 1000000) || case when r > 0 then ', ' || public._sw_words(r) else '' end;
  end if;
  r := n % 1000000000;
  return 'bilioni ' || public._sw_words(n / 1000000000) || case when r > 0 then ', ' || public._sw_words(r) else '' end;
end $$;

create or replace function public._en_words(n bigint)
returns text language plpgsql immutable as $$
declare
  ones text[] := array['One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve',
                       'Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  tens text[] := array['','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  r bigint;
begin
  if n = 0 then return ''; end if;
  if n < 20 then return ones[n]; end if;
  if n < 100 then return tens[n / 10] || case when n % 10 > 0 then '-' || ones[n % 10] else '' end; end if;
  if n < 1000 then
    r := n % 100;
    return ones[n / 100] || ' Hundred' || case when r > 0 then ' and ' || public._en_words(r) else '' end;
  end if;
  if n < 1000000 then
    r := n % 1000;
    return public._en_words(n / 1000) || ' Thousand' || case when r = 0 then '' when r < 100 then ' and ' else ' ' end || public._en_words(r);
  end if;
  if n < 1000000000 then
    r := n % 1000000;
    return public._en_words(n / 1000000) || ' Million' || case when r = 0 then '' when r < 100 then ' and ' else ' ' end || public._en_words(r);
  end if;
  r := n % 1000000000;
  return public._en_words(n / 1000000000) || ' Billion' || case when r = 0 then '' when r < 100 then ' and ' else ' ' end || public._en_words(r);
end $$;

create or replace function public.amount_words_en(p numeric)
returns text language plpgsql immutable as $$
declare n bigint := trunc(abs(p)); cents int := round((abs(p) - trunc(abs(p))) * 100);
begin
  if n = 0 and cents = 0 then return 'Zero Shillings Only'; end if;
  return trim(public._en_words(n)) || ' Shillings'
         || case when cents > 0 then ' and ' || public._en_words(cents) || ' Cents' else '' end || ' Only';
end $$;

-- ---------------------------------------------------------------------------
-- Receipt numbering — the counter row is locked inside the posting transaction,
-- so two simultaneous payments can never receive the same number.
-- ---------------------------------------------------------------------------
create or replace function public.issue_receipt(p_txn uuid, p_officer text default null)
returns public.receipts language plpgsql security definer set search_path = public as $$
declare
  t public.finance_transactions; p public.parishes; s text; n bigint; r public.receipts;
begin
  select * into t from public.finance_transactions where id = p_txn;
  select * into r from public.receipts where transaction_id = p_txn;
  if r.id is not null then return r; end if;
  select * into p from public.parishes where id = t.parish_id;
  s := to_char(t.txn_date, 'YYYY');
  insert into public.receipt_counters (parish_id, series, last_no) values (t.parish_id, s, 0)
    on conflict (parish_id, series) do nothing;
  update public.receipt_counters set last_no = last_no + 1
   where parish_id = t.parish_id and series = s returning last_no into n;
  insert into public.receipts (parish_id, receipt_no, series, seq, transaction_id, issued_by, receiving_officer,
                               payer_name, amount, amount_words_sw, amount_words_en)
  values (t.parish_id, coalesce(p.receipt_prefix, p.code) || '-' || s || '-' || lpad(n::text, 6, '0'), s, n, t.id,
          auth.uid(), p_officer, t.payer_name, t.amount, public.amount_words_sw(t.amount), public.amount_words_en(t.amount))
  returning * into r;
  return r;
end $$;

-- ---------------------------------------------------------------------------
-- Journal generation
-- ---------------------------------------------------------------------------
create or replace function public.write_journal(p_txn uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  t public.finance_transactions; c public.contribution_categories; e uuid; other uuid; dr uuid; cr uuid;
begin
  select * into t from public.finance_transactions where id = p_txn;
  if t.status <> 'posted' then return null; end if;
  select * into c from public.contribution_categories where id = t.category_id;
  if t.kind = 'income' then
    other := coalesce(c.income_account_id,
                      (select id from public.ledger_accounts where parish_id = t.parish_id and account_type = 'income' order by code limit 1));
    dr := t.money_account_id; cr := other;
  elsif t.kind = 'expense' then
    other := coalesce(c.expense_account_id,
                      (select id from public.ledger_accounts where parish_id = t.parish_id and account_type = 'expense' order by code limit 1));
    dr := other; cr := t.money_account_id;
  elsif t.kind = 'transfer' then
    dr := t.to_account_id; cr := t.money_account_id;
  else  -- opening_balance / adjustment: against equity
    other := (select id from public.ledger_accounts where parish_id = t.parish_id and account_type = 'equity' order by code limit 1);
    dr := t.money_account_id; cr := other;
  end if;
  if dr is null or cr is null then
    raise exception 'Akaunti za journal hazijawekwa kwa aina hii (missing ledger account for %)', t.kind using errcode = 'P0001';
  end if;
  if t.sign = -1 then other := dr; dr := cr; cr := other; end if;   -- reversal swaps sides
  insert into public.journal_entries (parish_id, transaction_id, entry_date, memo)
  values (t.parish_id, t.id, t.txn_date, coalesce(t.description, t.kind) || ' #' || t.txn_no) returning id into e;
  insert into public.journal_lines (entry_id, account_id, fund_id, debit, credit) values
    (e, dr, t.fund_id, t.amount, 0),
    (e, cr, t.fund_id, 0, t.amount);
  return e;
end $$;

-- ---------------------------------------------------------------------------
-- POST A PAYMENT (michango / zaka / mavuno / ujenzi / sadaka …)
--
-- p fields: idempotency_key (uuid, required), amount, txn_date, category_id,
--   campaign_id, pledge_id, parishioner_id, family_id, org_unit_id, payer_name,
--   payment_method, money_account_id, reference_no, description, period_month,
--   allocations [{pledge_id, amount}], confirm_duplicate (bool),
--   receiving_officer, envelope_id, event_id
-- Returns {status: posted | already_posted | possible_duplicate, ...}
-- ---------------------------------------------------------------------------
create or replace function public.post_payment(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_key uuid := (p->>'idempotency_key')::uuid;
  v_amount numeric(14,2) := round((p->>'amount')::numeric, 2);
  v_date date := coalesce((p->>'txn_date')::date, current_date);
  v_parish uuid := coalesce((p->>'parish_id')::uuid, public.default_parish_id());
  v_cat public.contribution_categories;
  v_campaign public.campaigns;
  v_pledge public.pledges;
  v_attr record;
  v_fy uuid;
  v_txn public.finance_transactions;
  v_dup public.finance_transactions;
  v_receipt public.receipts;
  v_method text := coalesce(nullif(p->>'payment_method',''), 'cash');
  v_period date;
  v_alloc jsonb; v_alloc_total numeric := 0;
  v_payer text;
begin
  if v_key is null then raise exception 'idempotency_key inahitajika' using errcode = 'P0001'; end if;

  -- 1. same submission already processed → return the original result (retry / double click)
  select * into v_txn from public.finance_transactions where idempotency_key = v_key;
  if v_txn.id is not null then
    select * into v_receipt from public.receipts where transaction_id = v_txn.id;
    return jsonb_build_object('status','already_posted','transaction_id',v_txn.id,'txn_no',v_txn.txn_no,
                              'receipt_no',v_receipt.receipt_no);
  end if;

  -- 2. validation
  if v_amount is null or v_amount <= 0 then raise exception 'Kiasi lazima kiwe zaidi ya sifuri (amount must be positive)' using errcode = 'P0001'; end if;
  if v_amount > 1000000000 then raise exception 'Kiasi ni kikubwa mno (amount too large)' using errcode = 'P0001'; end if;
  select * into v_cat from public.contribution_categories
   where id = (p->>'category_id')::uuid and parish_id = v_parish and is_active;
  if v_cat.id is null then raise exception 'Aina ya mchango haijulikani (unknown category)' using errcode = 'P0001'; end if;
  if v_cat.kind = 'expense' then raise exception 'Tumia record_expense kwa matumizi' using errcode = 'P0001'; end if;
  if v_method not in ('cash','cheque','bank_transfer','mobile_money','envelope','other') then
    raise exception 'Njia ya malipo si sahihi (invalid payment method)' using errcode = 'P0001';
  end if;
  if v_method in ('bank_transfer','mobile_money') and coalesce(btrim(p->>'reference_no'),'') = '' then
    raise exception 'Namba ya kumbukumbu inahitajika kwa malipo ya benki/simu (reference required)' using errcode = 'P0001';
  end if;
  if nullif(p->>'parishioner_id','') is null and nullif(p->>'family_id','') is null
     and nullif(p->>'org_unit_id','') is null and coalesce(btrim(p->>'payer_name'),'') = '' then
    raise exception 'Mlipaji anahitajika (payer required)' using errcode = 'P0001';
  end if;

  select * into v_attr from public.resolve_attribution((p->>'parishioner_id')::uuid, (p->>'family_id')::uuid, (p->>'org_unit_id')::uuid);

  if not public.has_perm('finance.record', coalesce(v_attr.org_unit_id, v_attr.jumuiya_id)) then
    raise exception 'Huna ruhusa ya kurekodi malipo (permission denied)' using errcode = '42501';
  end if;

  v_fy := public.assert_period_open(v_parish, v_date);

  if nullif(p->>'campaign_id','') is not null then
    select * into v_campaign from public.campaigns where id = (p->>'campaign_id')::uuid and parish_id = v_parish;
    if v_campaign.id is null or v_campaign.category_id <> v_cat.id then
      raise exception 'Kampeni hailingani na aina ya mchango (campaign/category mismatch)' using errcode = 'P0001';
    end if;
    if v_campaign.status = 'closed' then raise exception 'Kampeni % imefungwa', v_campaign.name using errcode = 'P0001'; end if;
  end if;

  if v_cat.uses_period_month then
    v_period := date_trunc('month', coalesce((p->>'period_month')::date, v_date))::date;
  end if;

  -- 3. obligation (pledge) the payment is taken against
  if nullif(p->>'pledge_id','') is not null then
    select * into v_pledge from public.pledges where id = (p->>'pledge_id')::uuid and parish_id = v_parish;
    if v_pledge.id is null or v_pledge.status <> 'active' then
      raise exception 'Ahadi haipo au haiko hai (pledge not active)' using errcode = 'P0001';
    end if;
    if v_campaign.id is null then select * into v_campaign from public.campaigns where id = v_pledge.campaign_id; end if;
    if v_pledge.campaign_id <> v_campaign.id then raise exception 'Ahadi si ya kampeni hii' using errcode = 'P0001'; end if;
  elsif v_campaign.id is not null then
    -- most specific obligation first: the person's own pledge, then their family's,
    -- then (for a payment made by a community itself) the community's
    select * into v_pledge from public.pledges
     where campaign_id = v_campaign.id and status = 'active'
       and ((nullif(p->>'parishioner_id','') is not null and parishioner_id = (p->>'parishioner_id')::uuid)
         or (v_attr.family_id is not null and family_id = v_attr.family_id)
         or (nullif(p->>'parishioner_id','') is null and v_attr.family_id is null and nullif(p->>'org_unit_id','') is not null
             and org_unit_id = (p->>'org_unit_id')::uuid))
     order by (parishioner_id is not null) desc, (family_id is not null) desc
     limit 1;
  end if;

  v_payer := coalesce(nullif(btrim(p->>'payer_name'),''),
                      (select full_name from public.parishioners where id = (p->>'parishioner_id')::uuid),
                      (select family_name from public.families where id = v_attr.family_id),
                      (select name from public.org_units where id = v_attr.org_unit_id));

  -- 4. possible duplicate (same payer, amount, category and day) — ask the user to confirm
  if not coalesce((p->>'confirm_duplicate')::boolean, false) then
    select * into v_dup from public.finance_transactions t
     where t.parish_id = v_parish and t.sign = 1 and t.reversed_by_id is null and t.status <> 'rejected'
       and t.category_id = v_cat.id and t.amount = v_amount and t.txn_date = v_date
       and t.campaign_id is not distinct from v_campaign.id
       and t.parishioner_id is not distinct from (p->>'parishioner_id')::uuid
       and t.family_id is not distinct from v_attr.family_id
       and t.org_unit_id is not distinct from v_attr.org_unit_id
       and t.period_month is not distinct from v_period
       and lower(coalesce(t.payer_name,'')) = lower(coalesce(v_payer,''))
     limit 1;
    if v_dup.id is not null then
      return jsonb_build_object('status','possible_duplicate','existing_transaction_id',v_dup.id,'existing_txn_no',v_dup.txn_no,
        'message','Malipo kama haya yamesharekodiwa leo. Thibitisha kama ni malipo mapya.');
    end if;
  end if;

  -- 5. ledger row
  insert into public.finance_transactions (
    parish_id, idempotency_key, kind, amount, status, txn_date, financial_year_id, period_month,
    category_id, campaign_id, pledge_id, fund_id, money_account_id,
    parishioner_id, family_id, org_unit_id, jumuiya_id, kigango_id, payer_name,
    payment_method, reference_no, description, event_id, envelope_id, recorded_by, approved_by, posted_at)
  values (
    v_parish, v_key, 'income', v_amount, 'posted', v_date, v_fy, v_period,
    v_cat.id, v_campaign.id, v_pledge.id, v_cat.fund_id, public.money_account_for(v_parish, v_method, (p->>'money_account_id')::uuid),
    (p->>'parishioner_id')::uuid, v_attr.family_id, v_attr.org_unit_id, v_attr.jumuiya_id, v_attr.kigango_id,
    v_payer, v_method, nullif(btrim(p->>'reference_no'),''), nullif(btrim(p->>'description'),''),
    (p->>'event_id')::uuid, (p->>'envelope_id')::uuid, auth.uid(), auth.uid(), now())
  returning * into v_txn;

  -- 6. allocation to obligations
  if jsonb_typeof(p->'allocations') = 'array' and jsonb_array_length(p->'allocations') > 0 then
    for v_alloc in select * from jsonb_array_elements(p->'allocations') loop
      perform 1 from public.pledges pl where pl.id = (v_alloc->>'pledge_id')::uuid and pl.status = 'active' and pl.parish_id = v_parish;
      if not found then raise exception 'Ahadi % haipo/haiko hai', v_alloc->>'pledge_id' using errcode = 'P0001'; end if;
      insert into public.payment_allocations (transaction_id, pledge_id, amount)
      values (v_txn.id, (v_alloc->>'pledge_id')::uuid, round((v_alloc->>'amount')::numeric, 2));
      v_alloc_total := v_alloc_total + round((v_alloc->>'amount')::numeric, 2);
    end loop;
    if v_alloc_total > v_amount then raise exception 'Mgawanyo unazidi kiasi kilicholipwa (allocations exceed amount)' using errcode = 'P0001'; end if;
  elsif v_pledge.id is not null then
    insert into public.payment_allocations (transaction_id, pledge_id, amount) values (v_txn.id, v_pledge.id, v_amount);
  end if;

  -- 7. accounting, receipt, envelope, audit
  perform public.write_journal(v_txn.id);
  v_receipt := public.issue_receipt(v_txn.id, nullif(p->>'receiving_officer',''));
  if v_txn.envelope_id is not null then
    update public.envelopes set status = 'returned', returned_on = v_date, transaction_id = v_txn.id where id = v_txn.envelope_id;
  end if;
  insert into public.audit_log (actor_id, action, table_name, row_id, new_data)
  values (auth.uid(), 'post_payment', 'finance_transactions', v_txn.id::text, to_jsonb(v_txn));

  return jsonb_build_object('status','posted','transaction_id',v_txn.id,'txn_no',v_txn.txn_no,
    'receipt_no',v_receipt.receipt_no,'receipt_id',v_receipt.id,'pledge_id',v_pledge.id,
    'pledge', (select to_jsonb(b) from public.v_pledge_balances b where b.pledge_id = v_pledge.id));
end $$;

-- ---------------------------------------------------------------------------
-- REVERSE a posted transaction (correction). The original stays untouched
-- except for the link; a mirror row with sign = -1 is posted on p_date.
-- ---------------------------------------------------------------------------
create or replace function public.reverse_transaction(p_txn uuid, p_reason text, p_idempotency_key uuid, p_date date default current_date)
returns jsonb language plpgsql security definer set search_path = public as $$
declare o public.finance_transactions; r public.finance_transactions; v_fy uuid;
begin
  select * into r from public.finance_transactions where idempotency_key = p_idempotency_key;
  if r.id is not null then return jsonb_build_object('status','already_posted','transaction_id',r.id,'txn_no',r.txn_no); end if;
  select * into o from public.finance_transactions where id = p_txn for update;
  if o.id is null then raise exception 'Muamala haupo' using errcode = 'P0001'; end if;
  if not public.has_perm('finance.reverse', coalesce(o.org_unit_id, o.jumuiya_id)) then
    raise exception 'Huna ruhusa ya kufuta/kurekebisha muamala (permission denied)' using errcode = '42501';
  end if;
  if o.status <> 'posted' then raise exception 'Muamala haujathibitishwa — hauwezi kurudishwa' using errcode = 'P0001'; end if;
  if o.sign = -1 then raise exception 'Huu tayari ni muamala wa kurudisha (already a reversal)' using errcode = 'P0001'; end if;
  if o.reversed_by_id is not null then raise exception 'Muamala huu umesharudishwa (already reversed)' using errcode = 'P0001'; end if;
  if coalesce(btrim(p_reason),'') = '' then raise exception 'Sababu inahitajika (reason required)' using errcode = 'P0001'; end if;
  v_fy := public.assert_period_open(o.parish_id, p_date);

  insert into public.finance_transactions (
    parish_id, idempotency_key, kind, sign, amount, status, txn_date, financial_year_id, period_month,
    category_id, campaign_id, pledge_id, fund_id, money_account_id, to_account_id,
    parishioner_id, family_id, org_unit_id, jumuiya_id, kigango_id, payer_name, payment_method, reference_no,
    description, reverses_id, reversal_reason, event_id, recorded_by, approved_by, posted_at, legacy_receipt_no)
  values (
    o.parish_id, p_idempotency_key, o.kind, -1, o.amount, 'posted', p_date, v_fy, o.period_month,
    o.category_id, o.campaign_id, o.pledge_id, o.fund_id, o.money_account_id, o.to_account_id,
    o.parishioner_id, o.family_id, o.org_unit_id, o.jumuiya_id, o.kigango_id, o.payer_name, o.payment_method, o.reference_no,
    'Kurudisha muamala #' || o.txn_no || ': ' || p_reason, o.id, p_reason, o.event_id, auth.uid(), auth.uid(), now(), o.legacy_receipt_no)
  returning * into r;

  update public.finance_transactions set reversed_by_id = r.id, reversal_reason = p_reason where id = o.id;
  -- mirror allocations: views multiply allocation amounts by the transaction sign
  insert into public.payment_allocations (transaction_id, pledge_id, amount)
    select r.id, pledge_id, amount from public.payment_allocations where transaction_id = o.id;
  perform public.write_journal(r.id);
  update public.receipts set status = 'void', void_reason = p_reason where transaction_id = o.id;
  update public.envelopes set status = 'distributed', returned_on = null, transaction_id = null where transaction_id = o.id;
  insert into public.audit_log (actor_id, action, table_name, row_id, old_data, new_data, note)
  values (auth.uid(), 'reverse_transaction', 'finance_transactions', o.id::text, to_jsonb(o), to_jsonb(r), p_reason);
  return jsonb_build_object('status','posted','transaction_id',r.id,'txn_no',r.txn_no,'reverses_txn_no',o.txn_no);
end $$;

-- ---------------------------------------------------------------------------
-- EXPENSES: recorded as pending, posted only after a second person approves.
-- ---------------------------------------------------------------------------
create or replace function public.record_expense(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_key uuid := (p->>'idempotency_key')::uuid;
  v_parish uuid := coalesce((p->>'parish_id')::uuid, public.default_parish_id());
  v_amount numeric(14,2) := round((p->>'amount')::numeric, 2);
  v_date date := coalesce((p->>'txn_date')::date, current_date);
  v_cat public.contribution_categories; v_txn public.finance_transactions; v_fy uuid; v_req uuid;
  v_method text := coalesce(nullif(p->>'payment_method',''), 'cash');
begin
  if v_key is null then raise exception 'idempotency_key inahitajika' using errcode = 'P0001'; end if;
  select * into v_txn from public.finance_transactions where idempotency_key = v_key;
  if v_txn.id is not null then return jsonb_build_object('status','already_recorded','transaction_id',v_txn.id,'txn_no',v_txn.txn_no); end if;
  if not public.has_perm('finance.expense.record', null) then
    raise exception 'Huna ruhusa ya kurekodi matumizi (permission denied)' using errcode = '42501';
  end if;
  if v_amount is null or v_amount <= 0 then raise exception 'Kiasi lazima kiwe zaidi ya sifuri' using errcode = 'P0001'; end if;
  if coalesce(btrim(p->>'description'),'') = '' then raise exception 'Maelezo ya matumizi yanahitajika' using errcode = 'P0001'; end if;
  select * into v_cat from public.contribution_categories where id = (p->>'category_id')::uuid and parish_id = v_parish and kind = 'expense';
  if v_cat.id is null then raise exception 'Chagua aina ya matumizi (expense category)' using errcode = 'P0001'; end if;
  v_fy := public.assert_period_open(v_parish, v_date);
  insert into public.finance_transactions (parish_id, idempotency_key, kind, amount, status, txn_date, financial_year_id,
    category_id, campaign_id, fund_id, money_account_id, org_unit_id, payer_name, payment_method, reference_no, description,
    event_id, recorded_by)
  values (v_parish, v_key, 'expense', v_amount, 'pending', v_date, v_fy, v_cat.id, (p->>'campaign_id')::uuid,
    coalesce((p->>'fund_id')::uuid, v_cat.fund_id), public.money_account_for(v_parish, v_method, (p->>'money_account_id')::uuid),
    (p->>'org_unit_id')::uuid, nullif(btrim(p->>'payee'),''), v_method, nullif(btrim(p->>'reference_no'),''),
    btrim(p->>'description'), (p->>'event_id')::uuid, auth.uid())
  returning * into v_txn;
  insert into public.approval_requests (parish_id, request_type, transaction_id, requested_by)
  values (v_parish, 'expense', v_txn.id, auth.uid()) returning id into v_req;
  insert into public.audit_log (actor_id, action, table_name, row_id, new_data)
  values (auth.uid(), 'record_expense', 'finance_transactions', v_txn.id::text, to_jsonb(v_txn));
  return jsonb_build_object('status','pending_approval','transaction_id',v_txn.id,'txn_no',v_txn.txn_no,'approval_id',v_req);
end $$;

create or replace function public.decide_approval(p_request uuid, p_approve boolean, p_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare a public.approval_requests; t public.finance_transactions; f public.funds; v_avail numeric;
begin
  select * into a from public.approval_requests where id = p_request for update;
  if a.id is null or a.status <> 'pending' then raise exception 'Ombi halipo au limeshaamuliwa' using errcode = 'P0001'; end if;
  if not public.has_perm('finance.approve', null) then raise exception 'Huna ruhusa ya kuidhinisha' using errcode = '42501'; end if;
  if a.requested_by = auth.uid() then
    raise exception 'Huwezi kuidhinisha ombi lako mwenyewe (separation of duties)' using errcode = '42501';
  end if;
  select * into t from public.finance_transactions where id = a.transaction_id for update;
  if p_approve then
    perform public.assert_period_open(t.parish_id, t.txn_date);
    select * into f from public.funds where id = t.fund_id;
    if t.kind = 'expense' and f.is_restricted then
      select coalesce(sum(net_amount) filter (where kind = 'income'),0) - coalesce(sum(net_amount) filter (where kind = 'expense'),0)
        into v_avail from public.finance_transactions where fund_id = f.id and status = 'posted';
      if t.amount > v_avail then
        raise exception 'Mfuko maalumu % hauna fedha za kutosha (restricted fund balance % < %)', f.name, v_avail, t.amount using errcode = 'P0001';
      end if;
    end if;
    update public.finance_transactions set status = 'posted', approved_by = auth.uid(), posted_at = now() where id = t.id;
    perform public.write_journal(t.id);
  else
    update public.finance_transactions set status = 'rejected', approved_by = auth.uid() where id = t.id;
  end if;
  update public.approval_requests set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = auth.uid(), decided_at = now(), decision_note = p_note where id = a.id;
  insert into public.audit_log (actor_id, action, table_name, row_id, note)
  values (auth.uid(), case when p_approve then 'approve' else 'reject' end, 'approval_requests', a.id::text, p_note);
  return jsonb_build_object('status', case when p_approve then 'approved' else 'rejected' end, 'transaction_id', t.id);
end $$;

-- transfer between money accounts (e.g. cash deposited to bank) — not income
create or replace function public.post_transfer(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_key uuid := (p->>'idempotency_key')::uuid; v_parish uuid := coalesce((p->>'parish_id')::uuid, public.default_parish_id());
  v_date date := coalesce((p->>'txn_date')::date, current_date); v_txn public.finance_transactions; v_cat uuid;
begin
  select * into v_txn from public.finance_transactions where idempotency_key = v_key;
  if v_txn.id is not null then return jsonb_build_object('status','already_posted','transaction_id',v_txn.id); end if;
  if not public.has_perm('finance.approve', null) then raise exception 'Huna ruhusa' using errcode = '42501'; end if;
  if (p->>'from_account_id') = (p->>'to_account_id') then raise exception 'Akaunti mbili lazima zitofautiane' using errcode = 'P0001'; end if;
  select id into v_cat from public.contribution_categories where parish_id = v_parish and code = 'TRANSFER';
  insert into public.finance_transactions (parish_id, idempotency_key, kind, amount, status, txn_date, financial_year_id, category_id,
    money_account_id, to_account_id, payment_method, reference_no, description, recorded_by, approved_by, posted_at)
  values (v_parish, v_key, 'transfer', round((p->>'amount')::numeric,2), 'posted', v_date, public.assert_period_open(v_parish, v_date), v_cat,
    public.money_account_for(v_parish, 'cash', (p->>'from_account_id')::uuid), public.money_account_for(v_parish, 'cash', (p->>'to_account_id')::uuid),
    'other', nullif(btrim(p->>'reference_no'),''), coalesce(nullif(btrim(p->>'description'),''), 'Uhamisho wa fedha'), auth.uid(), auth.uid(), now())
  returning * into v_txn;
  perform public.write_journal(v_txn.id);
  return jsonb_build_object('status','posted','transaction_id',v_txn.id,'txn_no',v_txn.txn_no);
end $$;

-- ---------------------------------------------------------------------------
-- PLEDGES
-- ---------------------------------------------------------------------------
create or replace function public.create_pledge(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_parish uuid := coalesce((p->>'parish_id')::uuid, public.default_parish_id());
  v_attr record; v_pl public.pledges; c public.campaigns;
begin
  select * into c from public.campaigns where id = (p->>'campaign_id')::uuid and parish_id = v_parish;
  if c.id is null then raise exception 'Kampeni haipo' using errcode = 'P0001'; end if;
  if c.status = 'closed' then raise exception 'Kampeni imefungwa' using errcode = 'P0001'; end if;
  select * into v_attr from public.resolve_attribution((p->>'parishioner_id')::uuid, (p->>'family_id')::uuid, (p->>'org_unit_id')::uuid);
  if not public.has_perm('finance.pledge', coalesce(v_attr.org_unit_id, v_attr.jumuiya_id)) then
    raise exception 'Huna ruhusa ya kuweka ahadi' using errcode = '42501';
  end if;
  insert into public.pledges (parish_id, campaign_id, parishioner_id, family_id, org_unit_id, amount, pledged_on, due_on,
                              jumuiya_id, kigango_id, created_by)
  values (v_parish, c.id, (p->>'parishioner_id')::uuid,
          case when nullif(p->>'parishioner_id','') is null then (p->>'family_id')::uuid end,
          case when nullif(p->>'parishioner_id','') is null and nullif(p->>'family_id','') is null then (p->>'org_unit_id')::uuid end,
          round((p->>'amount')::numeric, 2), coalesce((p->>'pledged_on')::date, current_date), (p->>'due_on')::date,
          v_attr.jumuiya_id, v_attr.kigango_id, auth.uid())
  returning * into v_pl;
  return jsonb_build_object('status','created','pledge_id',v_pl.id);
exception when unique_violation then
  raise exception 'Mlipaji huyu tayari ana ahadi hai kwenye kampeni hii (active pledge exists)' using errcode = 'P0001';
end $$;

-- change the pledged amount (not the payments) — logged in the audit trail
create or replace function public.update_pledge_amount(p_pledge uuid, p_amount numeric, p_reason text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare pl public.pledges;
begin
  select * into pl from public.pledges where id = p_pledge for update;
  if pl.id is null or pl.status <> 'active' then raise exception 'Ahadi haipo/haiko hai' using errcode = 'P0001'; end if;
  if not public.has_perm('finance.pledge', coalesce(pl.org_unit_id, pl.jumuiya_id)) then raise exception 'Huna ruhusa' using errcode = '42501'; end if;
  if coalesce(btrim(p_reason),'') = '' then raise exception 'Sababu inahitajika' using errcode = 'P0001'; end if;
  update public.pledges set amount = round(p_amount, 2), status_reason = p_reason where id = p_pledge;
  return jsonb_build_object('status','updated');
end $$;

create or replace function public.cancel_pledge(p_pledge uuid, p_reason text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare pl public.pledges; v_received numeric;
begin
  select * into pl from public.pledges where id = p_pledge for update;
  if pl.id is null or pl.status <> 'active' then raise exception 'Ahadi haipo/haiko hai' using errcode = 'P0001'; end if;
  if not public.has_perm('finance.pledge', coalesce(pl.org_unit_id, pl.jumuiya_id)) then raise exception 'Huna ruhusa' using errcode = '42501'; end if;
  select coalesce(sum(a.amount * t.sign),0) into v_received
    from public.payment_allocations a join public.finance_transactions t on t.id = a.transaction_id
   where a.pledge_id = pl.id and t.status = 'posted';
  if v_received <> 0 then
    raise exception 'Ahadi ina malipo ya TZS % — punguza kiasi badala ya kufuta (pledge has payments)', v_received using errcode = 'P0001';
  end if;
  update public.pledges set status = 'cancelled', status_reason = p_reason where id = pl.id;
  return jsonb_build_object('status','cancelled');
end $$;

-- Move the unpaid part of a pledge into a new campaign (e.g. Mavuno 2025 → 2026)
-- without double counting: the old pledge is closed at what was paid.
create or replace function public.carry_forward_pledge(p_pledge uuid, p_new_campaign uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare pl public.pledges; b record; n public.pledges;
begin
  select * into pl from public.pledges where id = p_pledge for update;
  if pl.id is null or pl.status <> 'active' then raise exception 'Ahadi haipo/haiko hai' using errcode = 'P0001'; end if;
  if not public.has_perm('finance.pledge', coalesce(pl.org_unit_id, pl.jumuiya_id)) then raise exception 'Huna ruhusa' using errcode = '42501'; end if;
  select * into b from public.v_pledge_balances where pledge_id = pl.id;
  if b.outstanding <= 0 then raise exception 'Hakuna deni la kuhamisha (nothing outstanding)' using errcode = 'P0001'; end if;
  insert into public.pledges (parish_id, campaign_id, parishioner_id, family_id, org_unit_id, amount, pledged_on, due_on,
                              status, carried_from_id, jumuiya_id, kigango_id, created_by)
  values (pl.parish_id, p_new_campaign, pl.parishioner_id, pl.family_id, pl.org_unit_id, b.outstanding, current_date, null,
          'active', pl.id, pl.jumuiya_id, pl.kigango_id, auth.uid())
  returning * into n;
  update public.pledges set status = 'carried_forward', status_reason = 'Deni limehamishiwa ahadi ' || n.id where id = pl.id;
  return jsonb_build_object('status','carried','new_pledge_id',n.id,'amount',b.outstanding);
end $$;

-- ---------------------------------------------------------------------------
-- PERIOD LOCKING AND YEAR CLOSING
-- ---------------------------------------------------------------------------
create or replace function public.ensure_periods(p_fy uuid)
returns void language plpgsql security definer set search_path = public as $$
declare fy public.financial_years; d date;
begin
  select * into fy from public.financial_years where id = p_fy;
  d := date_trunc('month', fy.starts_on)::date;
  while d <= fy.ends_on loop
    insert into public.accounting_periods (financial_year_id, period_start, period_end)
    values (fy.id, greatest(d, fy.starts_on), least((d + interval '1 month - 1 day')::date, fy.ends_on))
    on conflict (financial_year_id, period_start) do nothing;
    d := (d + interval '1 month')::date;
  end loop;
end $$;

create or replace function public.set_period_lock(p_period uuid, p_locked boolean)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not public.has_perm('finance.period.lock', null) then raise exception 'Huna ruhusa' using errcode = '42501'; end if;
  update public.accounting_periods set is_locked = p_locked,
         locked_at = case when p_locked then now() end, locked_by = case when p_locked then auth.uid() end
   where id = p_period;
  insert into public.audit_log (actor_id, action, table_name, row_id) values (auth.uid(), case when p_locked then 'lock_period' else 'unlock_period' end, 'accounting_periods', p_period::text);
  return jsonb_build_object('status', case when p_locked then 'locked' else 'unlocked' end);
end $$;

create or replace function public.close_financial_year(p_fy uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_pending int;
begin
  if not public.has_perm('finance.period.lock', null) then raise exception 'Huna ruhusa' using errcode = '42501'; end if;
  select count(*) into v_pending from public.finance_transactions where financial_year_id = p_fy and status = 'pending';
  if v_pending > 0 then raise exception 'Kuna miamala % inayosubiri idhini — iamue kwanza', v_pending using errcode = 'P0001'; end if;
  perform public.ensure_periods(p_fy);
  update public.accounting_periods set is_locked = true, locked_at = now(), locked_by = auth.uid() where financial_year_id = p_fy;
  update public.financial_years set status = 'closed', closed_at = now(), closed_by = auth.uid() where id = p_fy;
  insert into public.audit_log (actor_id, action, table_name, row_id) values (auth.uid(), 'close_financial_year', 'financial_years', p_fy::text);
  return jsonb_build_object('status','closed');
end $$;

-- receipt reprint counter (the receipt content never changes)
create or replace function public.mark_receipt_printed(p_receipt uuid)
returns void language sql security definer set search_path = public as $$
  update public.receipts set print_count = print_count + 1, last_printed_at = now()
   where id = p_receipt
     and exists (select 1 from public.finance_transactions t where t.id = receipts.transaction_id)
     and (public.has_perm_anywhere('finance.read')
          or exists (select 1 from public.finance_transactions t where t.id = receipts.transaction_id
                     and (t.parishioner_id = public.my_parishioner_id() or t.family_id = public.my_family_id())))
$$;

-- public receipt verification by number + code (no personal data returned)
create or replace function public.verify_receipt(p_receipt_no text, p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select jsonb_build_object('valid', r.status = 'valid', 'status', r.status, 'receipt_no', r.receipt_no,
                    'amount', r.amount, 'issued_at', r.issued_at, 'parish', p.official_name)
                   from public.receipts r join public.parishes p on p.id = r.parish_id
                   where r.receipt_no = p_receipt_no and r.verification_code = upper(p_code)),
                  jsonb_build_object('valid', false, 'status', 'not_found'))
$$;


-- >>>>>>>>>>>>>>>>>>>> 20261015_04_finance_views.sql >>>>>>>>>>>>>>>>>>>>
-- ============================================================================
-- Minga Parish Management System — migration 04: calculation engine (read side)
--   These views/functions replace the workbook's SUM / SUMIFS / VLOOKUP report
--   formulas. All are SECURITY INVOKER, so Row Level Security limits each user
--   to the communities they may see. Only status = 'posted' rows count;
--   reversals carry sign = -1 so every total nets out automatically.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Ledger with names (replaces 'MIAMALA-YOTE' VLOOKUP-by-receipt sheet)
-- ---------------------------------------------------------------------------
create or replace view public.v_ledger with (security_invoker = true) as
select t.id, t.txn_no, t.parish_id, t.kind, t.sign, t.amount, t.net_amount, t.status, t.txn_date,
       fy.label as financial_year, t.period_month,
       t.category_id, c.code as category_code, c.name_sw as category_name, c.kind as category_kind,
       t.campaign_id, cp.name as campaign_name, cp.campaign_year,
       t.pledge_id, t.fund_id, f.name as fund_name, t.money_account_id, a.name as money_account_name,
       t.parishioner_id, t.family_id, fam.family_name, t.org_unit_id, ou.name as org_unit_name,
       t.jumuiya_id, j.name as jumuiya_name, t.kigango_id, k.name as kigango_name,
       t.payer_name, t.payment_method, t.reference_no, t.description,
       t.reverses_id, t.reversed_by_id, t.reversal_reason,
       r.receipt_no, r.status as receipt_status, t.legacy_receipt_no,
       t.recorded_by, t.approved_by, t.posted_at, t.created_at, t.event_id, t.envelope_id
from public.finance_transactions t
join public.financial_years fy on fy.id = t.financial_year_id
join public.contribution_categories c on c.id = t.category_id
left join public.campaigns cp on cp.id = t.campaign_id
left join public.funds f on f.id = t.fund_id
left join public.ledger_accounts a on a.id = t.money_account_id
left join public.families fam on fam.id = t.family_id
left join public.org_units ou on ou.id = t.org_unit_id
left join public.org_units j on j.id = t.jumuiya_id
left join public.org_units k on k.id = t.kigango_id
left join public.receipts r on r.transaction_id = t.id;

-- ---------------------------------------------------------------------------
-- Pledge balances (replaces PANGIWA / TOA / BADO-ZIADA / % columns)
--   received    = payments applied to the pledge (reversals subtract)
--   paid        = part of received that counts against the pledge (≤ pledge)
--   outstanding = pledge − paid, never negative
--   excess      = received above the pledge, shown separately (never as negative debt)
-- ---------------------------------------------------------------------------
create or replace view public.v_pledge_balances with (security_invoker = true) as
select pl.id as pledge_id, pl.parish_id, pl.campaign_id, cp.name as campaign_name, cp.campaign_year,
       cp.category_id, c.code as category_code, c.name_sw as category_name,
       pl.parishioner_id, pr.full_name as parishioner_name, pl.family_id, fam.family_name,
       pl.org_unit_id, ou.name as org_unit_name,
       coalesce(pl.jumuiya_id, ou.id) as jumuiya_id, pl.kigango_id,
       pl.amount as pledged, pl.status, pl.pledged_on, pl.due_on, pl.carried_from_id,
       coalesce(x.received, 0) as received,
       least(coalesce(x.received, 0), pl.amount) as paid,
       case when pl.status = 'active' then greatest(pl.amount - coalesce(x.received, 0), 0) else 0 end as outstanding,
       greatest(coalesce(x.received, 0) - pl.amount, 0) as excess,
       round(least(coalesce(x.received, 0) / pl.amount, 1) * 100, 2) as completion_pct,
       x.payment_count, x.last_payment_on,
       (pl.status = 'active' and pl.due_on is not null and pl.due_on < current_date
        and coalesce(x.received, 0) < pl.amount) as is_overdue,
       pl.source, cp.giver_level, cp.amount_mode, cp.frequency
from public.pledges pl
join public.campaigns cp on cp.id = pl.campaign_id
join public.contribution_categories c on c.id = cp.category_id
left join public.parishioners pr on pr.id = pl.parishioner_id
left join public.families fam on fam.id = pl.family_id
left join public.org_units ou on ou.id = pl.org_unit_id
left join lateral (
  select sum(a.amount * t.sign) as received,
         count(*) filter (where t.sign = 1) - count(*) filter (where t.sign = -1) as payment_count,
         max(t.txn_date) filter (where t.sign = 1) as last_payment_on
  from public.payment_allocations a
  join public.finance_transactions t on t.id = a.transaction_id and t.status = 'posted'
  where a.pledge_id = pl.id
) x on true
where pl.status <> 'cancelled';

-- ---------------------------------------------------------------------------
-- Campaign progress (whole campaign)
-- ---------------------------------------------------------------------------
create or replace view public.v_campaign_progress with (security_invoker = true) as
select cp.id as campaign_id, cp.parish_id, cp.name, cp.campaign_year, cp.status, cp.starts_on, cp.ends_on,
       c.id as category_id, c.code as category_code, c.name_sw as category_name, c.kind as category_kind,
       coalesce(cp.target_amount, tg.target_total, 0) as target,
       coalesce(pb.pledged, 0) as pledged,
       coalesce(pb.outstanding, 0) as outstanding_pledges,
       coalesce(pb.excess, 0) as pledge_excess,
       coalesce(col.collected, 0) as collected,
       coalesce(col.payers, 0) as payers,
       case when coalesce(cp.target_amount, tg.target_total, 0) > 0
            then round(coalesce(col.collected, 0) / coalesce(cp.target_amount, tg.target_total) * 100, 2) end as target_pct
from public.campaigns cp
join public.contribution_categories c on c.id = cp.category_id
left join (select campaign_id, sum(target_amount) as target_total from public.campaign_targets group by campaign_id) tg
       on tg.campaign_id = cp.id
left join (select campaign_id, sum(pledged) as pledged, sum(outstanding) as outstanding, sum(excess) as excess
           from public.v_pledge_balances where status = 'active' group by campaign_id) pb on pb.campaign_id = cp.id
left join (select campaign_id, sum(net_amount) as collected,
                  count(distinct coalesce(parishioner_id::text, family_id::text, org_unit_id::text, lower(payer_name))) as payers
           from public.finance_transactions where status = 'posted' and kind = 'income' group by campaign_id) col
       on col.campaign_id = cp.id;

-- ---------------------------------------------------------------------------
-- Campaign progress per community (replaces RIPORT YA MAVUNO / UJENZI,
-- REPT JUMUIYA…, VIGAN-… report sheets and the ledger's K/L/N/O columns:
--   WALICHOPANGIWA (target) · WALICHOTOA (collected) · KIASI BADO · % YA UTOAJI)
-- p_level: 'jumuiya' or 'kigango'
-- ---------------------------------------------------------------------------
create or replace function public.campaign_org_progress(p_campaign uuid, p_level text default 'jumuiya')
returns table (org_unit_id uuid, org_unit_name text, kigango_name text, target numeric, pledged numeric,
               collected numeric, balance numeric, excess numeric, pct numeric, payers bigint)
language sql stable set search_path = public as $$
  with units as (
    select o.id, o.name, k.name as kname
    from public.org_units o
    left join public.org_units k on k.id = public.org_ancestor_of_type(o.id, 'kigango')
    where o.unit_type = p_level or (p_level = 'jumuiya' and o.unit_type = 'group')
  ),
  tgt as (
    select case when p_level = 'kigango' then public.org_ancestor_of_type(ct.org_unit_id, 'kigango') else ct.org_unit_id end as uid,
           sum(ct.target_amount) as target
    from public.campaign_targets ct where ct.campaign_id = p_campaign group by 1
  ),
  col as (
    select case when p_level = 'kigango' then t.kigango_id else coalesce(t.jumuiya_id, t.org_unit_id) end as uid,
           sum(t.net_amount) as collected,
           count(distinct coalesce(t.parishioner_id::text, t.family_id::text, lower(t.payer_name))) as payers
    from public.finance_transactions t
    where t.campaign_id = p_campaign and t.status = 'posted' and t.kind = 'income'
    group by 1
  ),
  pld as (
    select case when p_level = 'kigango' then b.kigango_id else b.jumuiya_id end as uid, sum(b.pledged) as pledged
    from public.v_pledge_balances b where b.campaign_id = p_campaign and b.status = 'active' group by 1
  )
  select u.id, u.name, u.kname,
         coalesce(tgt.target, 0), coalesce(pld.pledged, 0), coalesce(col.collected, 0),
         greatest(coalesce(tgt.target, 0) - coalesce(col.collected, 0), 0),
         greatest(coalesce(col.collected, 0) - coalesce(tgt.target, 0), 0),
         case when coalesce(tgt.target, 0) > 0 then round(coalesce(col.collected, 0) / tgt.target * 100, 2) end,
         coalesce(col.payers, 0)
  from units u
  left join tgt on tgt.uid = u.id
  left join col on col.uid = u.id
  left join pld on pld.uid = u.id
  where tgt.uid is not null or col.uid is not null or pld.uid is not null
  order by u.kname nulls first, u.name
$$;

-- ---------------------------------------------------------------------------
-- SUMIFS engine: totals by community level, category and period
--   p_level: 'parish' | 'kigango' | 'jumuiya' | 'family' | 'parishioner'
-- ---------------------------------------------------------------------------
create or replace function public.contribution_totals(
  p_from date, p_to date, p_level text default 'jumuiya',
  p_category uuid default null, p_campaign uuid default null, p_scope uuid default null)
returns table (group_id uuid, group_name text, category_id uuid, category_name text,
               total numeric, payments bigint, reversals bigint)
language sql stable set search_path = public as $$
  select case p_level when 'parish' then t.parish_id when 'kigango' then t.kigango_id
                      when 'jumuiya' then coalesce(t.jumuiya_id, t.org_unit_id)
                      when 'family' then t.family_id else t.parishioner_id end,
         case p_level when 'parish' then (select official_name from public.parishes where id = t.parish_id)
                      when 'kigango' then (select name from public.org_units where id = t.kigango_id)
                      when 'jumuiya' then (select name from public.org_units where id = coalesce(t.jumuiya_id, t.org_unit_id))
                      when 'family' then (select family_name from public.families where id = t.family_id)
                      else (select full_name from public.parishioners where id = t.parishioner_id) end,
         t.category_id, c.name_sw,
         sum(t.net_amount), count(*) filter (where t.sign = 1), count(*) filter (where t.sign = -1)
  from public.finance_transactions t
  join public.contribution_categories c on c.id = t.category_id
  where t.status = 'posted' and t.kind = 'income'
    and t.txn_date between p_from and p_to
    and (p_category is null or t.category_id = p_category)
    and (p_campaign is null or t.campaign_id = p_campaign)
    and (case when p_scope is null then true else coalesce(t.org_unit_id, t.jumuiya_id) = any ((select public.units_within(p_scope))::uuid[]) end)
  group by 1, 2, 3, 4
  order by 2, 4
$$;

-- monthly totals for a year (dashboard trend, MONTHLY / ANNUAL collection reports)
create or replace function public.monthly_totals(p_year int, p_scope uuid default null)
returns table (month date, income numeric, expense numeric, zaka numeric, mavuno numeric, ujenzi numeric,
               sadaka numeric, special numeric, other numeric)
language sql stable set search_path = public as $$
  with m as (select generate_series(make_date(p_year,1,1), make_date(p_year,12,1), interval '1 month')::date as month)
  select m.month,
    coalesce(sum(t.net_amount) filter (where t.kind = 'income'), 0),
    coalesce(sum(t.net_amount) filter (where t.kind = 'expense'), 0),
    coalesce(sum(t.net_amount) filter (where t.kind = 'income' and c.kind = 'zaka'), 0),
    coalesce(sum(t.net_amount) filter (where t.kind = 'income' and c.kind = 'mavuno'), 0),
    coalesce(sum(t.net_amount) filter (where t.kind = 'income' and c.kind = 'ujenzi'), 0),
    coalesce(sum(t.net_amount) filter (where t.kind = 'income' and c.kind = 'sadaka'), 0),
    coalesce(sum(t.net_amount) filter (where t.kind = 'income' and c.kind in ('special','shukrani')), 0),
    coalesce(sum(t.net_amount) filter (where t.kind = 'income' and c.kind = 'income_other'), 0)
  from m
  left join public.finance_transactions t
    on t.status = 'posted' and date_trunc('month', t.txn_date)::date = m.month
   and (case when p_scope is null then true else coalesce(t.org_unit_id, t.jumuiya_id) = any ((select public.units_within(p_scope))::uuid[]) end)
  left join public.contribution_categories c on c.id = t.category_id
  group by m.month order by m.month
$$;

-- ---------------------------------------------------------------------------
-- ZAKA: January–December grid per person / family / community
--   (replaces PAROKIA DATA BASE columns Q…BL and the BM/BN/BO/BP counters —
--    with the legacy month-count bugs fixed, see FORMULA_MAPPING.md)
-- ---------------------------------------------------------------------------
create or replace function public.zaka_grid(p_year int, p_level text default 'parishioner', p_scope uuid default null)
returns table (group_id uuid, group_name text, jumuiya_name text,
               m01 numeric, m02 numeric, m03 numeric, m04 numeric, m05 numeric, m06 numeric,
               m07 numeric, m08 numeric, m09 numeric, m10 numeric, m11 numeric, m12 numeric,
               total numeric, months_paid int, months_unpaid int)
language sql stable set search_path = public as $$
  with z as (
    select case p_level when 'parishioner' then t.parishioner_id when 'family' then t.family_id
                        when 'jumuiya' then t.jumuiya_id else t.kigango_id end as gid,
           extract(month from t.period_month)::int as m, sum(t.net_amount) as amt
    from public.finance_transactions t
    join public.contribution_categories c on c.id = t.category_id and c.kind = 'zaka'
    where t.status = 'posted' and t.kind = 'income'
      and t.period_month >= make_date(p_year, 1, 1) and t.period_month < make_date(p_year + 1, 1, 1)
      and (case when p_scope is null then true else coalesce(t.org_unit_id, t.jumuiya_id) = any ((select public.units_within(p_scope))::uuid[]) end)
    group by 1, 2
  ),
  -- months elapsed in the year (a month not yet reached is not "unpaid")
  lim as (select case when p_year < extract(year from current_date) then 12
                      when p_year > extract(year from current_date) then 0
                      else extract(month from current_date)::int end as months)
  select z.gid,
         case p_level when 'parishioner' then (select full_name from public.parishioners where id = z.gid)
                      when 'family' then (select family_name from public.families where id = z.gid)
                      else (select name from public.org_units where id = z.gid) end,
         case p_level when 'parishioner' then (select o.name from public.parishioners p join public.org_units o on o.id = p.jumuiya_id where p.id = z.gid)
                      when 'family' then (select o.name from public.families f join public.org_units o on o.id = f.jumuiya_id where f.id = z.gid)
                      else null end,
         sum(amt) filter (where m = 1), sum(amt) filter (where m = 2), sum(amt) filter (where m = 3),
         sum(amt) filter (where m = 4), sum(amt) filter (where m = 5), sum(amt) filter (where m = 6),
         sum(amt) filter (where m = 7), sum(amt) filter (where m = 8), sum(amt) filter (where m = 9),
         sum(amt) filter (where m = 10), sum(amt) filter (where m = 11), sum(amt) filter (where m = 12),
         sum(amt),
         (count(*) filter (where amt > 0))::int,
         greatest((select months from lim) - (count(*) filter (where amt > 0 and m <= (select months from lim)))::int, 0)
  from z
  group by z.gid
  order by 3 nulls last, 2
$$;

-- ---------------------------------------------------------------------------
-- Accounting views
-- ---------------------------------------------------------------------------
create or replace view public.v_account_balances with (security_invoker = true) as
select a.id as account_id, a.parish_id, a.code, a.name, a.account_type, a.money_kind,
       coalesce(sum(l.debit), 0) as total_debit, coalesce(sum(l.credit), 0) as total_credit,
       case when a.account_type in ('asset','expense') then coalesce(sum(l.debit) - sum(l.credit), 0)
            else coalesce(sum(l.credit) - sum(l.debit), 0) end as balance
from public.ledger_accounts a
left join public.journal_lines l on l.account_id = a.id
group by a.id;

create or replace view public.v_fund_balances with (security_invoker = true) as
select f.id as fund_id, f.parish_id, f.code, f.name, f.is_restricted,
       coalesce(sum(t.net_amount) filter (where t.kind = 'income'), 0) as income,
       coalesce(sum(t.net_amount) filter (where t.kind = 'expense'), 0) as expenses,
       coalesce(sum(t.net_amount) filter (where t.kind = 'income'), 0)
       - coalesce(sum(t.net_amount) filter (where t.kind = 'expense'), 0) as balance
from public.funds f
left join public.finance_transactions t on t.fund_id = f.id and t.status = 'posted'
group by f.id;

-- cashbook with opening balance and running balance for one money account
create or replace function public.cashbook(p_account uuid, p_from date, p_to date)
returns table (txn_date date, txn_no bigint, receipt_no text, description text, payer text,
               money_in numeric, money_out numeric, balance numeric)
language sql stable set search_path = public as $$
  with mv as (
    select t.txn_date, t.txn_no, r.receipt_no,
           coalesce(t.description, c.name_sw) as description, t.payer_name,
           case when (t.kind in ('income','opening_balance','adjustment') and t.money_account_id = p_account)
                  or (t.kind = 'transfer' and t.to_account_id = p_account) then t.net_amount else 0 end as money_in,
           case when (t.kind = 'expense' and t.money_account_id = p_account)
                  or (t.kind = 'transfer' and t.money_account_id = p_account) then t.net_amount else 0 end as money_out
    from public.finance_transactions t
    join public.contribution_categories c on c.id = t.category_id
    left join public.receipts r on r.transaction_id = t.id
    where t.status = 'posted' and (t.money_account_id = p_account or t.to_account_id = p_account)
  ),
  opening as (select coalesce(sum(money_in - money_out), 0) as bal from mv where txn_date < p_from)
  select null::date, null::bigint, null::text, 'SALIO LA KUANZIA (opening balance)', null::text, null::numeric, null::numeric,
         (select bal from opening)
  union all
  select txn_date, txn_no, receipt_no, description, payer_name, money_in, money_out,
         (select bal from opening) + sum(money_in - money_out) over (order by txn_date, txn_no)
  from mv where txn_date between p_from and p_to
$$;

create or replace view public.v_receipt_register with (security_invoker = true) as
select r.id, r.receipt_no, r.series, r.seq, r.issued_at, r.status, r.void_reason, r.print_count,
       r.payer_name, r.amount, r.amount_words_sw, r.receiving_officer,
       t.txn_no, t.txn_date, t.payment_method, t.reference_no, c.name_sw as category_name,
       j.name as jumuiya_name, k.name as kigango_name, t.parishioner_id, t.family_id, t.jumuiya_id, t.kigango_id
from public.receipts r
join public.finance_transactions t on t.id = r.transaction_id
join public.contribution_categories c on c.id = t.category_id
left join public.org_units j on j.id = t.jumuiya_id
left join public.org_units k on k.id = t.kigango_id;

-- ---------------------------------------------------------------------------
-- Integrity / reconciliation checks (Uhakiki wa Fedha)
-- ---------------------------------------------------------------------------
create or replace function public.finance_integrity_checks()
returns table (check_code text, description text, problem_count bigint, ok boolean)
language sql stable set search_path = public as $$
  with checks as (
    select 'posted_without_journal' as code, 'Miamala iliyothibitishwa bila journal' as d,
           (select count(*) from public.finance_transactions t where t.status = 'posted'
              and not exists (select 1 from public.journal_entries e where e.transaction_id = t.id)) as n
    union all
    select 'unbalanced_journal', 'Journal zisizolingana (debit ≠ credit)',
           (select count(*) from (select entry_id from public.journal_lines group by entry_id having sum(debit) <> sum(credit)) x)
    union all
    select 'journal_amount_mismatch', 'Journal ≠ kiasi cha muamala',
           (select count(*) from public.finance_transactions t join public.journal_entries e on e.transaction_id = t.id
             where (select sum(debit) from public.journal_lines l where l.entry_id = e.id) <> t.amount)
    union all
    select 'income_without_receipt', 'Mapato yasiyo na risiti (mbali na kumbukumbu za zamani)',
           (select count(*) from public.finance_transactions t where t.status = 'posted' and t.kind = 'income' and t.sign = 1
              and t.import_batch_id is null and not exists (select 1 from public.receipts r where r.transaction_id = t.id))
    union all
    select 'allocation_exceeds_payment', 'Mgawanyo unaozidi kiasi cha malipo',
           (select count(*) from (select a.transaction_id from public.payment_allocations a join public.finance_transactions t on t.id = a.transaction_id
              group by a.transaction_id, t.amount having sum(a.amount) > t.amount) x)
    union all
    select 'reversal_link_broken', 'Reversal zisizo na kiungo sahihi',
           (select count(*) from public.finance_transactions o where o.reversed_by_id is not null
              and not exists (select 1 from public.finance_transactions r where r.id = o.reversed_by_id and r.reverses_id = o.id and r.amount = o.amount))
    union all
    select 'pending_expenses', 'Matumizi yanayosubiri idhini',
           (select count(*) from public.finance_transactions where status = 'pending')
    union all
    select 'ledger_vs_accounts', 'Jumla ya mapato (ledger) ≠ jumla ya akaunti za mapato',
           (select case when abs(coalesce((select sum(net_amount) from public.finance_transactions where status = 'posted' and kind = 'income'),0)
                   - coalesce((select sum(l.credit - l.debit) from public.journal_lines l join public.ledger_accounts a on a.id = l.account_id and a.account_type = 'income'),0)) < 0.005
                   then 0 else 1 end)
  )
  select code, d, n, n = 0 or code = 'pending_expenses' from checks
$$;

-- ---------------------------------------------------------------------------
-- Dashboard summary (one round trip for the finance dashboard)
-- ---------------------------------------------------------------------------
-- integrity alerts are for parish-wide finance roles; for anyone else they would be
-- computed over the whole ledger and then hidden by RLS anyway
create or replace function public.dashboard_alerts()
returns jsonb language sql stable set search_path = public as $$
  select case when public.has_perm('finance.read')
              then (select jsonb_agg(to_jsonb(c)) from public.finance_integrity_checks() c where not c.ok) end
$$;

create or replace function public.parish_dashboard(p_year int default extract(year from current_date)::int, p_scope uuid default null)
returns jsonb language sql stable set search_path = public as $$
  with t as (
    select t.*, c.kind as ck from public.finance_transactions t join public.contribution_categories c on c.id = t.category_id
    where t.status = 'posted'
      and (case when p_scope is null then true else coalesce(t.org_unit_id, t.jumuiya_id) = any ((select public.units_within(p_scope))::uuid[]) end)
  ),
  y as (select * from t where extract(year from txn_date) = p_year)
  select jsonb_build_object(
    'year', p_year,
    'counts', jsonb_build_object(
       'parishioners', (select count(*) from public.parishioners where membership_status = 'active'
                          and (case when p_scope is null then true else jumuiya_id = any ((select public.units_within(p_scope))::uuid[]) end)),
       'families', (select count(*) from public.families where status = 'active'
                          and (case when p_scope is null then true else jumuiya_id = any ((select public.units_within(p_scope))::uuid[]) end)),
       'jumuiya', (select count(*) from public.org_units where unit_type = 'jumuiya' and is_active
                          and (case when p_scope is null then true else id = any ((select public.units_within(p_scope))::uuid[]) end)),
       'vigango', (select count(*) from public.org_units where unit_type = 'kigango' and is_active
                          and (case when p_scope is null then true else id = any ((select public.units_within(p_scope))::uuid[]) end))),
    'totals', jsonb_build_object(
       'income_year', coalesce((select sum(net_amount) from y where kind = 'income'), 0),
       'income_month', coalesce((select sum(net_amount) from y where kind = 'income'
                                  and date_trunc('month', txn_date) = date_trunc('month', current_date)), 0),
       'expenses_year', coalesce((select sum(net_amount) from y where kind = 'expense'), 0),
       'zaka', coalesce((select sum(net_amount) from y where kind = 'income' and ck = 'zaka'), 0),
       'mavuno', coalesce((select sum(net_amount) from y where kind = 'income' and ck = 'mavuno'), 0),
       'ujenzi', coalesce((select sum(net_amount) from y where kind = 'income' and ck = 'ujenzi'), 0),
       'sadaka', coalesce((select sum(net_amount) from y where kind = 'income' and ck = 'sadaka'), 0),
       'special', coalesce((select sum(net_amount) from y where kind = 'income' and ck in ('special','shukrani')), 0),
       'outstanding_pledges', coalesce((select sum(outstanding) from public.v_pledge_balances b where b.status = 'active'
                                        and (case when p_scope is null then true else b.jumuiya_id = any ((select public.units_within(p_scope))::uuid[]) end)), 0),
       'cash_available', coalesce((select sum(net_amount) filter (where kind in ('income','opening_balance','adjustment'))
                                   - coalesce(sum(net_amount) filter (where kind = 'expense'), 0) from t), 0)),
    'monthly', (select jsonb_agg(to_jsonb(m) order by m.month) from public.monthly_totals(p_year, p_scope) m),
    'campaigns', (select jsonb_agg(to_jsonb(v) order by v.collected desc) from public.v_campaign_progress v
                   where v.campaign_year = p_year and p_scope is null),
    'recent', (select jsonb_agg(x) from (select txn_no, txn_date, payer_name, category_name, net_amount,
                                                 coalesce(receipt_no, 'Excel #' || legacy_receipt_no) as receipt_no,
                                                 coalesce(jumuiya_name, org_unit_name, kigango_name) as jumuiya_name
                                          from public.v_ledger l where l.status = 'posted' and l.txn_date <= current_date
                                            and (case when p_scope is null then true else coalesce(l.org_unit_id, l.jumuiya_id) = any ((select public.units_within(p_scope))::uuid[]) end)
                                          order by l.txn_date desc, l.txn_no desc limit 10) x),
    'alerts', public.dashboard_alerts()
  )
$$;


